edits.oldText:
export function statusLabel(status: "open" | "closed") {
  if (status === "open") return "Open";
  if (status === "closed") return "Closed";
  return "Closed";
}

edits.newText:
const STATUS_LABELS = {
  open: "Open",
  closed: "Closed",
} as const;

export function statusLabel(status: "open" | "closed") {
  return STATUS_LABELS[status];
}
